SELECT analytics_order_facts.region, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 5 AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'mid_market' AND analytics_order_facts.payment_method = 'wallet' GROUP BY analytics_order_facts.region ORDER BY contribution_margin DESC, analytics_order_facts.region ASC LIMIT 12
